1	#pragma once
2	
3	#include "utils.cuh"
4	
5	template <int D, int CHUNK = 16>
6	struct K1Layouts {
7	    using QKLayout = decltype(make_layout(make_shape(Int<CHUNK>{}, Int<D>{}), LayoutRight{}));
8	    using GLayout = decltype(make_layout(make_shape(Int<CHUNK>{}, Int<D>{}), LayoutRight{}));
9	    using MMALayout = decltype(tile_to_shape(
10	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
11	        make_shape(Int<CHUNK>{}, Int<D>{}),
12	        LayoutLeft{}
13	    ));
14	    using BetaSmemLayout = Layout<Shape<Int<32>>, Stride<Int<1>>>;
15	    using GTotalLayout = Layout<Shape<Int<D>>, Stride<Int<1>>>;
16	    using LMLayout = decltype(tile_to_shape(
17	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
18	        make_shape(Int<CHUNK>{}, Int<CHUNK>{}),
19	        LayoutLeft{}
20	    ));
21	    using LF32Layout = decltype(make_layout(make_shape(Int<CHUNK>{}, Int<CHUNK>{}), LayoutRight{}));
22	    using TransposedLMLayout = decltype(tile_to_shape(
23	        GMMA::Layout_MN_INTER_Atom<cute::bfloat16_t>{},
24	        make_shape(Int<CHUNK>{}, Int<CHUNK>{}),
25	        LayoutRight{}
26	    ));
27	
28	    using TMABetaSmemLayout = BetaSmemLayout;  // 1D TMA, no dummy dim
29	    using TMAQKLayout = decltype(prepend(QKLayout{}));
30	    using TMAVOLayout = decltype(composition(
31	        MMALayout{}.layout_a(),
32	        MMALayout{}.offset(),
33	        prepend(MMALayout{}.layout_b())
34	    ));
35	    using TMAGLayout = decltype(prepend(GLayout{}));
36	    using TMALMLayout = decltype(composition(
37	        LMLayout{}.layout_a(),
38	        LMLayout{}.offset(),
39	        prepend(LMLayout{}.layout_b())
40	    ));
41	    using TMAGTotalSmemLayout = decltype(prepend(GTotalLayout{}));
42	};
43	
44	template <class Layouts>
45	struct SharedStorageK1 {
46	    using BF16 = cutlass::bfloat16_t;
47	    using QKLayout = typename Layouts::QKLayout;
48	    using GLayout = typename Layouts::GLayout;
49	    using BetaSmemLayout = typename Layouts::BetaSmemLayout;
50	    using GTotalLayout = typename Layouts::GTotalLayout;
51	    using LMLayout = typename Layouts::LMLayout;
52	    using MMALayout = typename Layouts::MMALayout;
53	
54	    // Phase A: q, k, g alive
55	    // Phase B: k_decayed, q_decayed, k_inv, L, INV, Mqk alive
56	    // These don't overlap → union saves ~14KB shared memory
57	    union {
58	        struct {
59	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<QKLayout>> q;
60	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<QKLayout>> k;
61	            alignas(128) cute::ArrayEngine<float, cute::cosize_v<GLayout>> g;
62	        };
63	        struct {
64	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> k_decayed;
65	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> q_decayed;
66	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> k_inv;
67	            alignas(128) cute::ArrayEngine<float, cute::cosize_v<LMLayout>> L;
68	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<LMLayout>> INV;
69	            alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<LMLayout>> Mqk;
70	        };
71	    };
72	
73	    alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<BetaSmemLayout>> beta;
74	
75	    union {
76	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<QKLayout>> g_bf16;      // TMA load target
77	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> k_restored;
78	    };
79	    union {
80	        alignas(128) cute::ArrayEngine<float, cute::cosize_v<GTotalLayout>> dt_bias;  // TMA load target
81	        alignas(128) cute::ArrayEngine<float, cute::cosize_v<GTotalLayout>> g_total;
82	    };
83	    alignas(16) cutlass::arch::ClusterTransactionBarrier tma_load_barrier;
84	};
85	
86	// Build prefix-sum of per-sequence tile counts, so Kernel 1 can map
87	// global_tile_idx -> seq_idx with an O(log N) binary search instead of an
88	// O(N) linear scan per CTA in varlen mode.
89	__global__ void _flash_kda_build_tile_prefix(
90	    int64_t const* __restrict__ cu_seqlens,
91	    int N,
92	    int chunk,
93	    int* __restrict__ tile_prefix
94	) {
95	    if (threadIdx.x == 0) {
96	        int acc = 0;
97	        tile_prefix[0] = 0;
98	        for (int i = 0; i < N; ++i) {
99	            int slen = int(cu_seqlens[i + 1] - cu_seqlens[i]);
100	            acc += (slen + chunk - 1) / chunk;
101	            tile_prefix[i + 1] = acc;
102	        }
103	    }
104	}
105	
106	// ==================== Kernel 1: Prepare ====================
107	template <
108	    class TmaLoadQ,
109	    class TmaLoadK,
110	    class TmaLoadBeta,
111	    class TmaLoadG,
112	    class TmaLoadDtBias,
113	    class TmaStoreWsKD, class TmaStoreWsQD, class TmaStoreWsKR,
114	    class TmaStoreWsGT, class TmaStoreWsINV, class TmaStoreWsMqk,
115	    int CHUNK,
116	    int D,
117	    int NumThreads,
118	    bool IsVarlen = true
119	>
120	__global__ void __launch_bounds__(NumThreads, 8) _flash_kda_fwd_prepare(
121	    CUTE_GRID_CONSTANT TmaLoadQ const tma_load_q,
122	    CUTE_GRID_CONSTANT TmaLoadK const tma_load_k,
123	    CUTE_GRID_CONSTANT TmaLoadBeta const tma_load_beta,
124	    CUTE_GRID_CONSTANT TmaLoadG const tma_load_g,
125	    CUTE_GRID_CONSTANT TmaLoadDtBias const tma_load_dt_bias,
126	    CUTE_GRID_CONSTANT TmaStoreWsKD const tma_store_ws_kd,
127	    CUTE_GRID_CONSTANT TmaStoreWsQD const tma_store_ws_qd,
128	    CUTE_GRID_CONSTANT TmaStoreWsKR const tma_store_ws_kr,
129	    CUTE_GRID_CONSTANT TmaStoreWsGT const tma_store_ws_gt,
130	    CUTE_GRID_CONSTANT TmaStoreWsINV const tma_store_ws_inv,
131	    CUTE_GRID_CONSTANT TmaStoreWsMqk const tma_store_ws_mqk,
132	    float scale,
133	    int T_total,
134	    int H,
135	    int N,
136	    int64_t const* cu_seqlens,
137	    int total_tiles,
138	    float const* A_log_ptr,
139	    float gate_scale,
140	    int const* tile_prefix
141	) {
142	    // --- constants
143	    using BF16 = cutlass::bfloat16_t;
144	    using Layouts = K1Layouts<D, CHUNK>;
145	    using MMALayout = typename Layouts::MMALayout;
146	    using QKLayout = typename Layouts::QKLayout;
147	    using GLayout = typename Layouts::GLayout;
148	    using BetaSmemLayout = typename Layouts::BetaSmemLayout;
149	    using GTotalLayout = typename Layouts::GTotalLayout;
150	    using LMLayout = typename Layouts::LMLayout;
151	    using LF32Layout = typename Layouts::LF32Layout;
152	    using TransposedLMLayout = typename Layouts::TransposedLMLayout;
153	    using TMAQKLayout = typename Layouts::TMAQKLayout;
154	    using TMABetaSmemLayout = typename Layouts::TMABetaSmemLayout;
155	    using TMAVOLayout = typename Layouts::TMAVOLayout;
156	    using TMALMLayout = typename Layouts::TMALMLayout;
157	    using TMAGTotalSmemLayout = typename Layouts::TMAGTotalSmemLayout;
158	    constexpr uint32_t kTmaTransactionBytes =
159	        uint32_t(cute::cosize_v<QKLayout>) * uint32_t(3 * sizeof(BF16)) +  // q + k + g_bf16
160	        uint32_t(32) * uint32_t(sizeof(BF16)) +  // beta (bf16, sigmoid fused)
161	        uint32_t(D) * uint32_t(sizeof(float));  // dt_bias
162	
163	    // --- shared memory
164	    extern __shared__ __align__(128) unsigned char shared_mem[];
165	    using SharedStorageT = SharedStorageK1<Layouts>;
166	    SharedStorageT& shared_storage = *reinterpret_cast<SharedStorageT*>(shared_mem);
167	
168	    // --- per-CTA tile info
169	    int global_tile_idx = blockIdx.x;
170	    int head_idx = blockIdx.y;
171	    int seq_idx, tiles_before, local_t;
172	    int64_t bos, eos;
173	    int seq_len, t_tiles_this_seq;
174	
175	    if constexpr (IsVarlen) {
176	        int lo = 0, hi = N;
177	        while (lo + 1 < hi) {
178	            int mid = (lo + hi) >> 1;
179	            if (tile_prefix[mid] <= global_tile_idx) lo = mid;
180	            else hi = mid;
181	        }
182	        seq_idx = lo;
183	        tiles_before = tile_prefix[lo];
184	        local_t = global_tile_idx - tiles_before;
185	        bos = cu_seqlens[seq_idx];
186	        eos = cu_seqlens[seq_idx + 1];
187	    } else {
188	        int T_seq = T_total / N;
189	        int tiles_per_seq = (T_seq + CHUNK - 1) / CHUNK;
190	        seq_idx = global_tile_idx / tiles_per_seq;
191	        tiles_before = seq_idx * tiles_per_seq;
192	        local_t = global_tile_idx - tiles_before;
193	        bos = seq_idx * T_seq;
194	        eos = bos + T_seq;
195	    }
196	    seq_len = int(eos - bos);
197	    t_tiles_this_seq = (seq_len + CHUNK - 1) / CHUNK;
198	    // Early exit for excess CTAs (total_tiles is an upper bound)
199	    if (local_t >= t_tiles_this_seq) return;
200	    // --- TMA load inputs (single-shot, no pipeline)
201	    // Only thread 0 issues TMA loads (not elect_one_sync which is per-warp)
202	    if (threadIdx.x == 0) {
203	        using BarrierType = cutlass::arch::ClusterTransactionBarrier::ValueType;
204	        shared_storage.tma_load_barrier.init(1);
205	        cutlass::arch::fence_barrier_init();  // generic init -> visible to async proxy (TMA complete-tx)
206	        shared_storage.tma_load_barrier.arrive_and_expect_tx(kTmaTransactionBytes);
207	
208	        Tensor g_q = tma_load_q.get_tma_tensor(make_shape(H, T_total, D));
209	        Tensor g_k = tma_load_k.get_tma_tensor(make_shape(H, T_total, D));
210	        Tensor g_beta = tma_load_beta.get_tma_tensor(make_shape(H * T_total));
211	
212	        auto cta_tma_load_q = tma_load_q.get_slice(Int<0>{});
213	        auto cta_tma_load_k = tma_load_k.get_slice(Int<0>{});
214	        auto cta_tma_load_beta = tma_load_beta.get_slice(Int<0>{});
215	
216	        auto qk_off = g_q.layout()(head_idx, int(bos) + local_t * CHUNK, 0);
217	        auto tile_shape_3d = make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{});
218	        auto tile_stride_3d = stride(g_q.layout());
219	        Tensor g_q_tile = make_tensor(g_q.data() + qk_off, make_layout(tile_shape_3d, tile_stride_3d));
220	        Tensor g_k_tile = make_tensor(g_k.data() + qk_off, make_layout(tile_shape_3d, tile_stride_3d));
221	
222	        int beta_linear = head_idx * T_total + (int(bos) + local_t * CHUNK);
223	        int beta_aligned = beta_linear & ~7;
224	        auto beta_off = g_beta.layout()(beta_aligned);
225	        Tensor g_beta_tile = make_tensor(g_beta.data() + beta_off, BetaSmemLayout{});
226	
227	        Tensor s_q_tile = make_tensor(make_smem_ptr(shared_storage.q.begin()), TMAQKLayout{});
228	        Tensor s_k_tile = make_tensor(make_smem_ptr(shared_storage.k.begin()), TMAQKLayout{});
229	        Tensor s_beta_tile = make_tensor(make_smem_ptr(shared_storage.beta.begin()), TMABetaSmemLayout{});
230	
231	        cute::copy(tma_load_q.with(reinterpret_cast<BarrierType&>(shared_storage.tma_load_barrier)),
232	            cta_tma_load_q.partition_S(g_q_tile), cta_tma_load_q.partition_D(s_q_tile));
233	        cute::copy(tma_load_k.with(reinterpret_cast<BarrierType&>(shared_storage.tma_load_barrier)),
234	            cta_tma_load_k.partition_S(g_k_tile), cta_tma_load_k.partition_D(s_k_tile));
235	        cute::copy(tma_load_beta.with(reinterpret_cast<BarrierType&>(shared_storage.tma_load_barrier)),
236	            cta_tma_load_beta.partition_S(g_beta_tile), cta_tma_load_beta.partition_D(s_beta_tile));
237	
238	        // TMA load g_bf16 (same gmem layout as q/k)
239	        Tensor g_g = tma_load_g.get_tma_tensor(make_shape(H, T_total, D));
240	        auto cta_tma_load_g = tma_load_g.get_slice(Int<0>{});
241	        Tensor g_g_tile = make_tensor(g_g.data() + qk_off, make_layout(tile_shape_3d, tile_stride_3d));
242	        Tensor s_g_bf16_tile = make_tensor(make_smem_ptr(shared_storage.g_bf16.begin()), TMAQKLayout{});
243	        cute::copy(tma_load_g.with(reinterpret_cast<BarrierType&>(shared_storage.tma_load_barrier)),
244	            cta_tma_load_g.partition_S(g_g_tile), cta_tma_load_g.partition_D(s_g_bf16_tile));
245	
246	        // TMA load dt_bias [H, D] → [D] slice for current head
247	        Tensor g_dt = tma_load_dt_bias.get_tma_tensor(make_shape(H, D));
248	        auto cta_tma_load_dt = tma_load_dt_bias.get_slice(Int<0>{});
249	        auto dt_off = g_dt.layout()(head_idx, 0);
250	        Tensor g_dt_tile = make_tensor(g_dt.data() + dt_off,
251	            make_layout(make_shape(Int<1>{}, Int<D>{}), stride(g_dt.layout())));
252	        Tensor s_dt_tile = make_tensor(make_smem_ptr(shared_storage.dt_bias.begin()), TMAGTotalSmemLayout{});
253	        cute::copy(tma_load_dt_bias.with(reinterpret_cast<BarrierType&>(shared_storage.tma_load_barrier)),
254	            cta_tma_load_dt.partition_S(g_dt_tile), cta_tma_load_dt.partition_D(s_dt_tile));
255	    }
256	
257	    // --- Compute a_log_exp (overlaps with TMA)
258	    float a_log_exp = expf(A_log_ptr[head_idx]);
259	    // --- Wait for TMA (q, k, beta, g_bf16, dt_bias)
260	    __syncthreads();
261	    shared_storage.tma_load_barrier.wait(0);
262	    cutlass::arch::fence_view_async_shared();
263	    __syncthreads();
264	
265	    // --- QK L2 Normalization ---
266	    int compute_tid = threadIdx.x;
267	    {
268	        constexpr int ELEMS_PER_THREAD = 8;
269	        constexpr int THREADS_PER_ROW = D / ELEMS_PER_THREAD;  // 16
270	        int my_row = threadIdx.x / THREADS_PER_ROW;
271	        int my_col = (threadIdx.x % THREADS_PER_ROW) * ELEMS_PER_THREAD;
272	
273	        BF16* q_smem = shared_storage.q.begin();
274	        BF16* k_smem = shared_storage.k.begin();
275	
276	        float q_vals[ELEMS_PER_THREAD], k_vals[ELEMS_PER_THREAD];
277	        float q_sq = 0.0f, k_sq = 0.0f;
278	
279	        #pragma unroll
280	        for (int i = 0; i < ELEMS_PER_THREAD; ++i) {
281	            float qv = bf16_to_f32(q_smem[my_row * D + my_col + i]);
282	            float kv = bf16_to_f32(k_smem[my_row * D + my_col + i]);
283	            q_vals[i] = qv;
284	            k_vals[i] = kv;
285	            q_sq += qv * qv;
286	            k_sq += kv * kv;
287	        }
288	
289	        #pragma unroll
290	        for (int delta = 8; delta >= 1; delta >>= 1) {
291	            q_sq += __shfl_xor_sync(0xFFFFFFFF, q_sq, delta);
292	            k_sq += __shfl_xor_sync(0xFFFFFFFF, k_sq, delta);
293	        }
294	
295	        float q_inv = rsqrtf(q_sq + 1e-6f);
296	        float k_inv = rsqrtf(k_sq + 1e-6f);
297	
298	        #pragma unroll
299	        for (int i = 0; i < ELEMS_PER_THREAD; ++i) {
300	            q_smem[my_row * D + my_col + i] = BF16(q_vals[i] * q_inv);
301	            k_smem[my_row * D + my_col + i] = BF16(k_vals[i] * k_inv);
302	        }
303	    }
304	    __syncthreads();
305	
306	    // --- Fused gate activation + cumsum + k tail zero-fill ---
307	    // Threads 0-127: gate(g_bf16 + dt_bias) → cumulative sum, eliminates raw-g smem round-trip
308	    // Threads 128-255: zero k for tail rows
309	    {
310	        int actual_len = min(CHUNK, seq_len - local_t * CHUNK);
311	        if (compute_tid < 128) {
312	            int col = compute_tid;
313	            BF16 const* g_bf16_smem = shared_storage.g_bf16.begin();
314	            float dt = shared_storage.dt_bias.begin()[col];
315	            float* g_smem = shared_storage.g.begin();
316	            float sum = 0.0f;
317	            #pragma unroll
318	            for (int row = 0; row < CHUNK; ++row) {
319	                float g_val;
320	                if (row < actual_len) {
321	                    g_val = bf16_to_f32(g_bf16_smem[row * D + col]) + dt;
322	                    g_val = a_log_exp * g_val;
323	                    g_val = gate_scale * sigmoid_tanh_approx_f32(g_val);
324	                } else {
325	                    g_val = 0.0f;
326	                }
327	                sum += g_val;
328	                g_smem[row * D + col] = sum;
329	            }
330	            shared_storage.g_total.begin()[col] = sum;
331	        } else {
332	            int col = compute_tid - 128;
333	            BF16* k_smem = shared_storage.k.begin();
334	            for (int row = actual_len; row < CHUNK; ++row) {
335	                k_smem[row * D + col] = BF16(0);
336	            }
337	        }
338	    }
339	    __syncthreads();
340	
341	    Tensor q_tile = make_tensor(make_smem_ptr(shared_storage.q.begin()), QKLayout{});
342	    Tensor k_tile = make_tensor(make_smem_ptr(shared_storage.k.begin()), QKLayout{});
343	    Tensor g_tile = make_tensor(make_smem_ptr(shared_storage.g.begin()), GLayout{});
344	    Tensor beta_tile = make_tensor(make_smem_ptr(shared_storage.beta.begin()), BetaSmemLayout{});
345	    int beta_smem_offset = (head_idx * T_total + int(bos) + local_t * CHUNK) & 7;
346	
347	    Tensor k_restored = make_tensor(make_smem_ptr(shared_storage.k_restored.begin()), MMALayout{});
348	    Tensor k_decayed = make_tensor(make_smem_ptr(shared_storage.k_decayed.begin()), MMALayout{});
349	    Tensor q_decayed = make_tensor(make_smem_ptr(shared_storage.q_decayed.begin()), MMALayout{});
350	    Tensor k_inv = make_tensor(make_smem_ptr(shared_storage.k_inv.begin()), MMALayout{});
351	    Tensor g_total = make_tensor(make_smem_ptr(shared_storage.g_total.begin()), GTotalLayout{});
352	
353	    // exp_g_total: compute exp(g_total) in smem before decay_apply
354	    if (compute_tid < 128) {
355	        float x = g_total(compute_tid);
356	        g_total(compute_tid) = ex2_approx_ftz_f32(x);
357	    }
358	    __syncthreads();
359	
360	// decay_apply
361	    if (compute_tid < 256) {
362	        static_assert(D % 64 == 0);
363	        static_assert(CHUNK % 8 == 0);
364	
365	        int lane = compute_tid % 32;
366	        int warp_id = compute_tid / 32;
367	        int g = lane / 4;
368	        int t = lane % 4;
369	
370	        auto vec8_2d = make_shape(_1{}, _8{});
371	        auto vec8_1d = make_shape(_8{});
372	        auto thr2_2d = make_shape(_1{}, _2{});
373	        auto thr2_1d = make_shape(_2{});
374	
375	        constexpr int N_M = CHUNK / 8;
376	        constexpr int N_N = D / 64;
377	        constexpr int N_TILES = N_M * N_N;
378	
379	        float reg_g[N_TILES][2];
380	        BF16  reg_q[N_TILES][2];
381	        BF16  reg_k[N_TILES][2];
382	        float reg_gt[N_TILES][2];
383	
384	        #pragma unroll
385	        for (int m_blk = 0; m_blk < CHUNK; m_blk += 8) {
386	            #pragma unroll
387	            for (int n_blk = 0; n_blk < D; n_blk += 64) {
388	                int tile_idx = (m_blk / 8) * N_N + (n_blk / 64);
389	                int row = m_blk + ((warp_id + g) % 8);
390	                int col_base = n_blk + g * 8;
391	                int col_tile = col_base / 8;
392	
393	                Tensor tile_g  = local_tile(g_tile, vec8_2d, make_coord(row, col_tile));
394	                Tensor tile_q  = local_tile(q_tile, vec8_2d, make_coord(row, col_tile));
395	                Tensor tile_k  = local_tile(k_tile, vec8_2d, make_coord(row, col_tile));
396	                Tensor tile_gt = local_tile(g_total, vec8_1d, make_coord(col_tile));
397	
398	                Tensor s_g  = local_tile(tile_g,  thr2_2d, make_coord(0, t));
399	                Tensor s_q  = local_tile(tile_q,  thr2_2d, make_coord(0, t));
400	                Tensor s_k  = local_tile(tile_k,  thr2_2d, make_coord(0, t));
401	                Tensor s_gt = local_tile(tile_gt, thr2_1d, make_coord(t));
402	
403	                Tensor r_g  = make_tensor_like<float>(s_g);
404	                Tensor r_q  = make_tensor_like<BF16>(s_q);
405	                Tensor r_k  = make_tensor_like<BF16>(s_k);
406	                Tensor r_gt = make_tensor_like<float>(s_gt);
407	
408	                cute::copy(AutoVectorizingCopy{}, s_g, r_g);
409	                cute::copy(AutoVectorizingCopy{}, s_q, r_q);
410	                cute::copy(AutoVectorizingCopy{}, s_k, r_k);
411	                cute::copy(AutoVectorizingCopy{}, s_gt, r_gt);
412	
413	                #pragma unroll
414	                for (int v = 0; v < 2; ++v) {
415	                    reg_g[tile_idx][v]  = r_g(0, v);
416	                    reg_q[tile_idx][v]  = r_q(0, v);
417	                    reg_k[tile_idx][v]  = r_k(0, v);
418	                    reg_gt[tile_idx][v] = r_gt(v);
419	                }
420	            }
421	        }
422	
423	        // Sync before writing to union'd smem (q/k/g → k_decayed/q_decayed/k_inv)
424	        // Safe: all 256 threads enter this if block (compute_tid < 256 always true)
425	        __syncthreads();
426	
427	        #pragma unroll
428	        for (int m_blk = 0; m_blk < CHUNK; m_blk += 8) {
429	            #pragma unroll
430	            for (int n_blk = 0; n_blk < D; n_blk += 64) {
431	                int tile_idx = (m_blk / 8) * N_N + (n_blk / 64);
432	                int row = m_blk + ((warp_id + g) % 8);
433	                int col_base = n_blk + g * 8;
434	                int col_tile = col_base / 8;
435	
436	                Tensor tile_qd = local_tile(q_decayed, vec8_2d, make_coord(row, col_tile));
437	                Tensor tile_kd = local_tile(k_decayed, vec8_2d, make_coord(row, col_tile));
438	                Tensor tile_kr = local_tile(k_restored, vec8_2d, make_coord(row, col_tile));
439	                Tensor tile_ki = local_tile(k_inv, vec8_2d, make_coord(row, col_tile));
440	
441	                Tensor s_qd = local_tile(tile_qd, thr2_2d, make_coord(0, t));
442	                Tensor s_kd = local_tile(tile_kd, thr2_2d, make_coord(0, t));
443	                Tensor s_kr = local_tile(tile_kr, thr2_2d, make_coord(0, t));
444	                Tensor s_ki = local_tile(tile_ki, thr2_2d, make_coord(0, t));
445	
446	                Tensor r_qd = make_tensor_like<BF16>(s_qd);
447	                Tensor r_kd = make_tensor_like<BF16>(s_kd);
448	                #pragma unroll
449	                for (int v = 0; v < 2; ++v) {
450	                    float g = reg_g[tile_idx][v];
451	                    BF16 q = reg_q[tile_idx][v];
452	                    BF16 k = reg_k[tile_idx][v];
453	                    BF16 exp_cumsum = BF16(ex2_approx_ftz_f32(g));
454	                    r_qd(0, v) = q * exp_cumsum * BF16(scale);
455	                    r_kd(0, v) = k * exp_cumsum;
456	                }
457	                cute::copy(AutoVectorizingCopy{}, r_qd, s_qd);
458	                cute::copy(AutoVectorizingCopy{}, r_kd, s_kd);
459	
460	                Tensor r_ki = make_tensor_like<BF16>(s_ki);
461	                Tensor r_kr = make_tensor_like<BF16>(s_kr);
462	                #pragma unroll
463	                for (int v = 0; v < 2; ++v) {
464	                    float g = reg_g[tile_idx][v];
465	                    BF16 k = reg_k[tile_idx][v];
466	                    BF16 inv_cumsum = BF16(ex2_approx_ftz_f32(-g));
467	                    r_ki(0, v) = k * inv_cumsum;
468	                    r_kr(0, v) = k * inv_cumsum * BF16(reg_gt[tile_idx][v]);
469	                }
470	                cute::copy(AutoVectorizingCopy{}, r_ki, s_ki);
471	                cute::copy(AutoVectorizingCopy{}, r_kr, s_kr);
472	            }
473	        }
474	
475	    }
476	    __syncthreads();
477	
478	    Tensor L_fp32 = make_tensor(make_smem_ptr(shared_storage.L.begin()), LF32Layout{});
479	    Tensor Mqk = make_tensor(make_smem_ptr(shared_storage.Mqk.begin()), LMLayout{});
